/**
 * Writer for the ratcheted JSON artifacts (`react-compiler-bailouts.json`,
 * `styling-budget.json`).
 *
 * These files are generated by their gate's `--update` mode and committed, so
 * they are also checked by `bun run pretty:check`. Writing them with a bare
 * `JSON.stringify(value, null, 2)` puts the two tools in direct conflict:
 * `JSON.stringify` always expands an array over multiple lines, Prettier
 * collapses one that fits inside `printWidth`. The bailout file has arrays of
 * short strings, so every `check:react-compiler:update` left the formatter
 * red — and `prettier --write` on it was undone by the next update. A closed
 * loop that no one could win.
 *
 * Formatting through Prettier itself, with the config it resolves for that
 * exact path, makes the two agree by construction rather than by hand-matching
 * rules that would drift the next time `printWidth` moves.
 */
import { writeFileSync } from 'node:fs';

/**
 * Serialize `value` as JSON and write it to `filePath`, formatted exactly as
 * `pretty:check` expects to find it.
 *
 * @param {string} filePath Absolute or cwd-relative path to write.
 * @param {unknown} value JSON-serializable value.
 */
export async function writeRatchetArtifact(filePath, value) {
  // Imported here, not at module load: only `--update` writes, and the check
  // path each gate runs in CI has no business failing because the formatter
  // could not be resolved.
  const { format, resolveConfig } = await import('prettier');
  // `editorconfig: true` because that is what the CLI behind `pretty:check`
  // does by default and the API does not. There is no `.editorconfig` here
  // today, and the point of this helper is that adding one could never make
  // the writer and the checker disagree again.
  const options = await resolveConfig(filePath, { editorconfig: true });
  const formatted = await format(JSON.stringify(value, null, 2), {
    ...options,
    filepath: filePath,
    parser: 'json',
  });
  writeFileSync(filePath, formatted);
}
